test("relative source references respect registered child roots, declared ranges and symlink exclusions", async () => {
	const data = fixture();
	let reader;
	try {
		mkdirSync(path.join(data.root, "child/src"), { recursive: true });
		writeFileSync(path.join(data.root, "child/src/实现.ts"), "first\nselected\nlast\n");
		writeFileSync(path.join(data.root, "private.txt"), "not registered as a source");
		symlinkSync(path.join(data.root, "private.txt"), path.join(data.root, "child/src/escape.ts"));
		writeFileSync(path.join(data.root, ".lumine/project.json"), JSON.stringify({
			schemaVersion: 2,
			workflowVersion: 2,
			locale: "en",
			repositories: [{
				id: "root",
				path: "."
			}, {
				id: "child",
				path: "child"
			}],
			wiki: { root: "docs/repo-wiki" }
		}));
		writeFileSync(path.join(data.root, "docs/repo-wiki/child.md"), `---
id: child-mechanism
title: Child mechanism
summary: A declaration is necessary but cannot bypass the source resolver.
type: mechanism
status: current
sources:
  - id: child-source
    repoId: child
    path: src/实现.ts
    startLine: 2
    endLine: 2
  - id: escaped-source
    repoId: child
    path: src/escape.ts
---
# Child
`);
		reader = await serveWiki(data.root, {
			port: 0,
			assetsRoot: data.assetsRoot
		});
		const resolve = (target) => fetch(`${reader.url}/api/reference?${new URLSearchParams({
			from: "child-mechanism",
			target
		})}`);
		const valid = await resolve("../../child/src/%E5%AE%9E%E7%8E%B0.ts#L2");
		assert.equal(valid.status, 200);
		assert.equal((await valid.json()).sourceId, "child-source");
		for (const target of [
			"../../child/src/实现.ts#L1-L2",
			"../../child/src/escape.ts",
			"../../private.txt",
			"../../child/src/../src/escape.ts"
		]) assert.notEqual((await resolve(target)).status, 200, target);
		const escapeSource = await fetch(`${reader.url}/api/source?document=child-mechanism&id=escaped-source`);
		assert.notEqual(escapeSource.status, 200);
	} finally {
		await reader?.close();
		data.close();
	}
});

